+  [value]
+  (cond
+    (nil? value) nil
+    (number? value) value
+    (string? value) (let [ms (.parse js/Date value)]
+                      (when-not (js/Number.isNaN ms) ms))
+    (and (some? value) (fn? (.-getTime value))) (let [ms (.getTime value)]
+                                                  (when-not (js/Number.isNaN ms) ms))
+    :else nil))
+
