+     :target-node-id target-node-id
+     :relation-kind relation-kind
+     :direction direction
+     :scope scope
+     :scope-json (canonical-scope-json scope)}))
+
+(defn- sha256-hex-24
+  [text]
+  (let [sha (Sha256.)]
+    (.update sha text)
+    (subs (crypt/byteArrayToHex (.digest sha)) 0 24)))
+
